  participants$;
  races$;
  selectedRaceId$;
  loading$;
  pdfExportLoading$;
  displayedColumns = [
    "id",
    "firstName",
    "lastName",
    "birthDate",
    "gender",
    "raceNumber",
    "team",
    "ageGroup",
    "race",
    "durationMs",
    "measuredAt",
    "actions"
  ];
